//! C backend for rdgen's arena-owned tagged-union AST representation.

use rdgen_ir::{Element, Grammar, Rule};

/// Emit the C declarations shared by generated parser code and consumers.
pub fn emit_ast(grammar: &Grammar) -> Result<String, String> {
    let mut output = String::from(
        "/* Generated by rdgen; do not edit. */\n"
            .to_owned()
            + "#ifndef RDGEN_AST_H\n#define RDGEN_AST_H\n\n"
            + "#include <stdbool.h>\n#include <stddef.h>\n\n"
            + "#include <string.h>\n\n"
            + "typedef struct rdgen_token { const char *text; size_t length; } rdgen_token;\n"
            + "typedef struct rdgen_arena rdgen_arena;\n"
            + "void *rdgen_arena_alloc(rdgen_arena *arena, size_t size);\n\n",
    );

    for rule in &grammar.rules {
        let name = c_type_name(&rule.name);
        output.push_str(&format!("typedef struct {name} {name};\n"));
    }
    output.push('\n');

    let mut collection_types = std::collections::HashSet::new();
    for rule in &grammar.rules {
        for alternative in &rule.alternatives {
            for element in &alternative.elements {
                emit_collection_types(&mut output, element, &mut collection_types);
            }
        }
    }
    if !collection_types.is_empty() {
        output.push('\n');
    }

    for rule in &grammar.rules {
        emit_rule(&mut output, rule)?;
    }
    output.push_str("#endif /* RDGEN_AST_H */\n");
    Ok(output)
}

fn emit_rule(output: &mut String, rule: &Rule) -> Result<(), String> {
    let name = c_type_name(&rule.name);
    output.push_str(&format!("typedef enum {name}_kind {{\n"));
    for (index, alternative) in rule.alternatives.iter().enumerate() {
        output.push_str(&format!("    {name}_{}\n", variant_name(rule, alternative, index)));
        if index + 1 != rule.alternatives.len() {
            output.push_str(",");
        }
    }
    output.push_str(&format!("}} {name}_kind;\n\n"));
    output.push_str(&format!("struct {name} {{\n    {name}_kind kind;\n    union {{\n"));
    for (index, alternative) in rule.alternatives.iter().enumerate() {
        let variant = variant_name(rule, alternative, index);
        output.push_str(&format!("        struct {{\n"));
        for field in &alternative.constructor.fields {
            let element = find_labeled_element(&alternative.elements, &field.source_label)
                .ok_or_else(|| format!("missing label '{}' in rule '{}'", field.source_label, rule.name))?;
            output.push_str(&format!("            {} {};\n", c_field_type(element), c_field_name(&field.field)));
        }
        output.push_str(&format!("        }} {variant};\n"));
    }
    output.push_str("    } as;\n};\n\n");
    Ok(())
}

fn variant_name(rule: &Rule, alternative: &rdgen_ir::Alternative, index: usize) -> String {
    if alternative.constructor.fields.is_empty() && alternative.constructor.type_name.0 == rule.name {
        format!("ALT{}", index + 1)
    } else {
        c_type_name(&alternative.constructor.type_name.0)
    }
}

fn find_labeled_element<'a>(elements: &'a [Element], label: &str) -> Option<&'a Element> {
    for element in elements {
        match element {
            Element::Rule { label: Some(name), .. }
            | Element::Token { label: Some(name), .. }
            | Element::Literal { label: Some(name), .. } if name == label => return Some(element),
            Element::Group { alternatives, .. } => {
                for alternative in alternatives {
                    if let Some(found) = find_labeled_element(alternative, label) { return Some(found); }
                }
            }
            Element::Repeat { element, .. } => {
                if let Some(found) = find_labeled_element(std::slice::from_ref(element.as_ref()), label) { return Some(found); }
            }
            _ => {}
        }
    }
    None
}

fn c_field_type(element: &Element) -> String {
    match element {
        Element::Rule { rule, .. } => format!("{} *", c_type_name(rule)),
        Element::Token { .. } | Element::Literal { .. } => "rdgen_token".into(),
        Element::Repeat { element, max: Some(1), .. } => c_collection_name(element, true),
        Element::Repeat { element, .. } => c_collection_name(element, false),
        Element::Group { .. } => "bool".into(),
    }
}

fn c_value_type(element: &Element) -> String {
    match element {
        Element::Rule { rule, .. } => format!("{} *", c_type_name(rule)),
        Element::Token { .. } | Element::Literal { .. } => "rdgen_token".into(),
        Element::Repeat { element, max: Some(1), .. } => c_collection_name(element, true),
        Element::Repeat { element, .. } => c_collection_name(element, false),
        Element::Group { .. } => "bool".into(),
    }
}

fn c_collection_key(element: &Element) -> String {
    match element {
        Element::Rule { rule, .. } => c_type_name(rule).trim_start_matches("rdgen_").to_owned(),
        Element::Token { .. } | Element::Literal { .. } => "token".into(),
        Element::Repeat { element, max: Some(1), .. } => format!("optional_{}", c_collection_key(element)),
        Element::Repeat { element, .. } => format!("list_{}", c_collection_key(element)),
        Element::Group { .. } => "group".into(),
    }
}

fn c_collection_name(element: &Element, optional: bool) -> String {
    format!("rdgen_{}_{}", c_collection_key(element), if optional { "optional" } else { "list" })
}

fn emit_collection_types(output: &mut String, element: &Element, emitted: &mut std::collections::HashSet<String>) {
    match element {
        Element::Repeat { element: child, max: Some(1), .. } | Element::Repeat { element: child, max: None, .. } => {
            emit_collection_types(output, child, emitted);
            let optional = matches!(element, Element::Repeat { max: Some(1), .. });
            let name = c_collection_name(child, optional);
            if !emitted.insert(name.clone()) { return; }
            if optional {
                output.push_str(&format!("typedef struct {{ bool present; {} value; }} {};\n", c_value_type(child), name));
            } else {
                output.push_str(&format!("typedef struct {{ {} *items; size_t length; }} {};\n", c_value_type(child), name));
            }
        }
        Element::Group { alternatives, .. } => {
            for alternative in alternatives {
                for child in alternative { emit_collection_types(output, child, emitted); }
            }
        }
        _ => {}
    }
}

fn c_type_name(name: &str) -> String {
    let mut result = String::from("rdgen_");
    for (index, character) in name.chars().enumerate() {
        if character.is_ascii_alphanumeric() || character == '_' {
            result.push(character.to_ascii_lowercase());
        } else {
            result.push('_');
        }
        if index == 0 && character.is_ascii_digit() { result.insert(result.len() - 1, '_'); }
    }
    result
}

fn c_field_name(name: &str) -> String {
    let mut result = String::new();
    for character in name.chars() {
        result.push(if character.is_ascii_alphanumeric() || character == '_' { character.to_ascii_lowercase() } else { '_' });
    }
    if result.is_empty() { "field".into() } else { result }
}

/// Emit the C AST header. Parser emission is intentionally separate from the
/// AST ABI while the C recursive-descent control-flow backend is developed.
pub fn emit(grammar: &Grammar) -> Result<String, String> {
    emit_ast(grammar)
}

/// Emit a C parser for the currently supported simple alternative shape.
///
/// Groups and repetitions are intentionally rejected until their C control
/// flow is implemented; silently treating them as empty productions would
/// make the generated parser unsound.
pub fn emit_parser(grammar: &Grammar) -> Result<String, String> {
    let mut output = emit_ast(grammar)?;
    let guard = "#endif /* RDGEN_AST_H */\n";
    let end = output.rfind(guard).ok_or_else(|| "generated AST is missing its include guard".to_owned())?;
    output.truncate(end);
    output.push_str(&(
        "typedef struct rdgen_parser rdgen_parser;\n"
            .to_owned()
            + "typedef size_t (*rdgen_skip_trivia_fn)(const char *source, size_t position);\n"
            + "typedef bool (*rdgen_scan_terminal_fn)(const char *source, size_t position, const char *name, rdgen_token *token, size_t *end);\n"
            + "typedef struct rdgen_error { const char *message; size_t position; } rdgen_error;\n"
            + "struct rdgen_parser { const char *source; size_t length; size_t position; rdgen_arena *arena; rdgen_skip_trivia_fn skip_trivia; rdgen_scan_terminal_fn scan_terminal; };\n"
            + "static void rdgen_set_error(rdgen_error *error, const char *message, size_t position) { if (error != NULL) { error->message = message; error->position = position; } }\n"
            + "static void rdgen_skip(rdgen_parser *parser) { if (parser->skip_trivia != NULL) { size_t next = parser->skip_trivia(parser->source, parser->position); if (next >= parser->position && next <= parser->length) parser->position = next; } }\n"
            + "static bool rdgen_expect_literal(rdgen_parser *parser, const char *literal, rdgen_token *token) { size_t length = strlen(literal); rdgen_skip(parser); if (parser->position + length <= parser->length && strncmp(parser->source + parser->position, literal, length) == 0) { token->text = parser->source + parser->position; token->length = length; parser->position += length; return true; } return false; }\n"
            + "rdgen_parser rdgen_parser_init(const char *source, size_t length, rdgen_arena *arena, rdgen_skip_trivia_fn skip_trivia, rdgen_scan_terminal_fn scan_terminal) { rdgen_parser parser = { source, length, 0, arena, skip_trivia, scan_terminal }; return parser; }\n\n"
    ));
    for rule in &grammar.rules {
        output.push_str(&format!("static {} *rdgen_parse_{}(rdgen_parser *parser, rdgen_error *error);\n", c_type_name(&rule.name), rule.name));
    }
    output.push('\n');
    for rule in &grammar.rules {
        emit_c_parser_rule(&mut output, rule)?;
    }
    let start = grammar.rules.first().ok_or_else(|| "grammar has no rules".to_owned())?;
    let start_name = c_type_name(&start.name);
    output.push_str(&format!(
        "{start_name} *rdgen_parse(rdgen_parser *parser, rdgen_error *error) {{ {start_name} *node = rdgen_parse_{}(parser, error); if (node == NULL) return NULL; rdgen_skip(parser); if (parser->position != parser->length) {{ rdgen_set_error(error, \"unexpected trailing input\", parser->position); return NULL; }} return node; }}\n\n",
        start.name
    ));
    output.push_str("#endif /* RDGEN_AST_H */\n");
    Ok(output)
}

fn emit_c_parser_rule(output: &mut String, rule: &Rule) -> Result<(), String> {
    let name = c_type_name(&rule.name);
    output.push_str(&format!("static {name} *rdgen_parse_{}(rdgen_parser *parser, rdgen_error *error) {{\n", rule.name));
    for (index, alternative) in rule.alternatives.iter().enumerate() {
        if alternative.elements.iter().any(|element| !is_c_supported_element(element)) {
            return Err(format!("C parser emitter does not yet support grouped or repeated elements in rule '{}'", rule.name));
        }
        output.push_str(&format!("    {{ size_t start_{index} = parser->position;\n"));
        for (element_index, element) in alternative.elements.iter().enumerate() {
            output.push_str(&format!("        {};\n", c_local_declaration(element, element_index)));
            output.push_str(&format!("        {}\n", c_parse_statement(element, element_index, index)?));
        }
        let variant = variant_name(rule, alternative, index);
        output.push_str(&format!("        {name} *node = ({name} *)rdgen_arena_alloc(parser->arena, sizeof(*node));\n        if (node == NULL) {{ rdgen_set_error(error, \"arena allocation failed\", parser->position); return NULL; }}\n        node->kind = {name}_{variant};\n"));
        for field in &alternative.constructor.fields {
            output.push_str(&format!("        node->as.{variant}.{} = {};\n", c_field_name(&field.field), c_local_name_for_label(&alternative.elements, &field.source_label)));
        }
        output.push_str(&format!("        return node;\n    rdgen_alt_fail_{index}:\n        parser->position = start_{index};\n    }}\n"));
    }
    output.push_str(&format!("    rdgen_set_error(error, \"no alternative for {}\", parser->position);\n    return NULL;\n}}\n\n", rule.name));
    Ok(())
}

fn is_c_supported_element(element: &Element) -> bool {
    match element {
        Element::Literal { .. } | Element::Token { .. } | Element::Rule { .. } => true,
        Element::Repeat { element, .. } => c_repeat_child(element).is_some_and(is_simple_element),
        Element::Group { .. } => false,
    }
}

fn is_simple_element(element: &Element) -> bool {
    matches!(element, Element::Literal { .. } | Element::Token { .. } | Element::Rule { .. })
}

fn c_local_name_for_label(elements: &[Element], label: &str) -> String {
    elements.iter().enumerate().find_map(|(index, element)| match element {
        Element::Rule { label: Some(name), .. }
        | Element::Token { label: Some(name), .. }
        | Element::Literal { label: Some(name), .. } if name == label => Some(c_local_name(element, index)),
        _ => None,
    }).unwrap_or_else(|| c_field_name(label))
}

fn c_local_name(element: &Element, index: usize) -> String {
    match element {
        Element::Rule { label: Some(label), .. }
        | Element::Token { label: Some(label), .. }
        | Element::Literal { label: Some(label), .. } => format!("value_{}", c_field_name(label)),
        _ => format!("element_{index}"),
    }
}

fn c_local_declaration(element: &Element, index: usize) -> String {
    if matches!(element, Element::Repeat { .. }) {
        return format!("size_t {}_count", c_local_name(element, index));
    }
    format!("{} {}", match element { Element::Rule { rule, .. } => format!("{} *", c_type_name(rule)), _ => "rdgen_token".into() }, c_local_name(element, index))
}

fn c_parse_statement(element: &Element, index: usize, alternative_index: usize) -> Result<String, String> {
    let local = c_local_name(element, index);
    match element {
        Element::Literal { value, .. } => Ok(format!("if (!rdgen_expect_literal(parser, {:?}, &{local})) goto rdgen_alt_fail_{alternative_index};", value)),
        Element::Token { token, .. } => Ok(format!("{{ size_t end_{index} = parser->position; if (parser->scan_terminal == NULL || !parser->scan_terminal(parser->source, parser->position, {:?}, &{local}, &end_{index}) || end_{index} <= parser->position || end_{index} > parser->length) goto rdgen_alt_fail_{alternative_index}; parser->position = end_{index}; }}", token)),
        Element::Rule { rule, .. } => Ok(format!("{local} = rdgen_parse_{}(parser, error); if ({local} == NULL) goto rdgen_alt_fail_{alternative_index};", rule)),
        Element::Repeat { element: child, max: Some(1), .. } => Ok(format!("{local}_count = 0; {{ size_t item_start_{index} = parser->position; {} if (parser->position != item_start_{index}) {local}_count = 1; else parser->position = item_start_{index}; }}", c_repeat_probe(c_repeat_child(child).ok_or_else(|| "C optional requires a single-element group".to_owned())?, index)?)),
        Element::Repeat { element: child, max: None, .. } => Ok(format!("{local}_count = 0; for (;;) {{ size_t item_start_{index} = parser->position; {} if (parser->position == item_start_{index}) {{ parser->position = item_start_{index}; break; }} {local}_count++; }}", c_repeat_probe(c_repeat_child(child).ok_or_else(|| "C repetition requires a single-element group".to_owned())?, index)?)),
        _ => Err("unsupported C parser element".into()),
    }
}

fn c_repeat_child(element: &Element) -> Option<&Element> {
    match element {
        Element::Group { alternatives, .. } if alternatives.len() == 1 && alternatives[0].len() == 1 => alternatives[0].first(),
        _ => None,
    }
}

fn c_repeat_probe(element: &Element, index: usize) -> Result<String, String> {
    let item = format!("repeat_item_{index}");
    match element {
        Element::Literal { value, .. } => Ok(format!("rdgen_token {item}; if (!rdgen_expect_literal(parser, {:?}, &{item})) parser->position = item_start_{index};", value)),
        Element::Token { token, .. } => Ok(format!("rdgen_token {item}; size_t repeat_end_{index} = parser->position; if (parser->scan_terminal == NULL || !parser->scan_terminal(parser->source, parser->position, {:?}, &{item}, &repeat_end_{index}) || repeat_end_{index} <= parser->position || repeat_end_{index} > parser->length) parser->position = item_start_{index}; else parser->position = repeat_end_{index};", token)),
        Element::Rule { rule, .. } => Ok(format!("{} *{item} = rdgen_parse_{}(parser, error); if ({item} == NULL) parser->position = item_start_{index};", c_type_name(rule), rule)),
        _ => Err("C repetitions currently require a literal, terminal, or rule child".into()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rdgen_grammar::compile;

    #[test]
    fn emits_arena_friendly_tagged_unions() {
        let grammar = compile(
            "grammar Expr; expr = value: number => Number(value: value) | left: number, \"+\", right: expr => Add(left: left, right: right); number = digit: \"0\" => Number(digit: digit);",
        ).unwrap();
        let generated = emit_ast(&grammar).unwrap();
        assert!(generated.contains("typedef struct rdgen_expr rdgen_expr;"));
        assert!(generated.contains("rdgen_expr * right;"));
        assert!(generated.contains("rdgen_token digit;"));
        assert!(generated.contains("rdgen_arena_alloc"));
    }

    #[test]
    fn emits_backtracking_parser_for_simple_alternatives() {
        let grammar = compile(
            "grammar Start; start = left: \"a\", right: item => Pair(left: left, right: right); item = \"b\" => Item();",
        ).unwrap();
        let generated = emit_parser(&grammar).unwrap();
        assert!(generated.contains("rdgen_parse_start"));
        assert!(generated.contains("rdgen_parser rdgen_parser_init"));
        assert!(generated.contains("rdgen_start *rdgen_parse("));
        assert!(generated.contains("rdgen_expect_literal(parser, \"a\""));
        assert!(generated.contains("node->as.rdgen_pair.left"));
        assert!(generated.contains("rdgen_alt_fail_0:"));
    }

    #[test]
    fn rejects_complex_elements_until_c_control_flow_exists() {
        let grammar = compile("grammar Start; start = ( \"a\" );").unwrap();
        let error = emit_parser(&grammar).unwrap_err();
        assert!(error.contains("does not yet support grouped or repeated elements"));
    }

    #[test]
    fn emits_simple_optional_and_repeated_consumption() {
        let grammar = compile("grammar Start; start = [ \"a\" ], { \"b\" } => Start();").unwrap();
        let generated = emit_parser(&grammar).unwrap();
        assert!(generated.contains("element_0_count = 0"));
        assert!(generated.contains("for (;;)"));
    }
}
